import {paperFigures} from './data/paper-figures.js';
import {esc,fmt} from './viz.js';
const value=(f,x)=>f.percent?`${fmt(100*x)}%`:fmt(x,4);
const intervalText=f=>f.ci_key?(f.table==='filter_summary'?'Whiskers are 95% confidence intervals for the mean, clustered by observation dataset.':'Whiskers are 95% confidence intervals for the mean over repeats on this fixed cloud.'):'No confidence intervals are supplied for this score summary; points show recorded means only.';
const comparison=f=>`${f.shown.length} of ${f.valid_methods} methods shown: the five best observed means, plus eigen when it is outside that group. The full table below contains every method in this setting.`;
export function mountPaperFigure(name,host){const f=paperFigures.find(f=>`paper-${f.id}`===name);if(!f)return false;
const rows=f.rows.map(r=>{const ci=f.ci_key?r[f.ci_key]:null,success=r.successful_trials??r.trials;return `<tr class="${r.provider==='custom'&&r.method==='eigen'?'paper-eigen-row':''}"><td>${r.rank??'—'}</td><td>${esc(r.display_name)}</td><td class="number-cell">${Number.isFinite(r[f.metric])?value(f,r[f.metric]):'Unavailable'}</td><td class="number-cell">${Number.isFinite(ci)?value(f,ci):'Unavailable'}</td><td>${success} / ${r.trials}</td><td>${fmt(100*(r.failure_rate??0))}%</td></tr>`;}).join('');
const failed=f.rows.filter(r=>(r.failure_rate??0)>0),failureNote=failed.length?`<p class="paper-failures"><b>Failed attempts in this setting:</b> ${failed.map(r=>`${esc(r.display_name)}: ${r.trials-r.successful_trials}/${r.trials}`).join('; ')}. Its plotted/table mean conditions on successful trials.</p>`:'';
const caption=`${f.benchmark} ${intervalText(f)} ${f.log?'The logarithmic axis shows tiny and large errors together; equal spacing represents multiplication, not addition. ':''}${comparison(f)} ${f.limit}`;
host.innerHTML=`<article class="paper-result" data-figure="${f.id}"><div class="paper-question"><span>THE QUESTION</span><p>${esc(f.question)}</p></div><div class="paper-metric"><b>What the metric means</b><p>${esc(f.meaning)}</p><div class="paper-formula">${esc(f.formula)}</div></div><figure class="paper-figure" aria-labelledby="caption-${f.id}"><a href="${f.image}" target="_blank" rel="noopener noreferrer" aria-label="Open Figure ${f.number} at full size"><picture><source media="(max-width: 800px)" srcset="${f.mobile_image}"><img src="${f.image}" alt="Figure ${f.number}: ${f.title}. ${f.best_names.join(', ')} has the ${f.direction==='higher'?'highest':'lowest'} observed mean, ${value(f,f.best_value)}. Eigen: ${value(f,f.eigen_value)}." width="920" height="460" loading="${f.number<3?'eager':'lazy'}"></picture></a><p class="paper-swipe">Select the figure to open the full-size version.</p><figcaption id="caption-${f.id}"><strong>Figure ${f.number}.</strong> ${esc(caption)}</figcaption></figure><div class="paper-finding"><div class="paper-best"><span>${f.direction==='higher'?'HIGHEST':'LOWEST'} OBSERVED MEAN</span><strong>${esc(f.best_names.join(' / '))}</strong><p>${value(f,f.best_value)} ${f.percent?'':esc(f.unit)} <span>· among ${f.valid_methods} methods at this setting</span></p></div><div class="paper-eigen"><span>EIGEN BASELINE</span><strong>${value(f,f.eigen_value)} ${f.percent?'':esc(f.unit)}</strong><p>Rank ${f.eigen_rank} of ${f.valid_methods} by this metric.</p></div></div><p class="paper-takeaway"><b>What this benchmark shows.</b> ${esc(f.finding)}</p>${failureNote}<div class="paper-downloads"><a href="${f.image}" download>SVG ↓</a><a href="${f.pdf}" download>PDF ↓</a><a href="${f.png}" download>PNG ↓</a><a href="${f.csv}" download>All ${f.total_methods} result rows · CSV ↓</a></div><details class="paper-full-table"><summary>Show all ${f.total_methods} methods, uncertainty, and failed attempts</summary><p class="table-caption">Rank is by the observed mean in this one setting. Close ranks do not imply a statistically established difference. Unavailable values are not ranked.</p><div class="table-scroll"><table><thead><tr><th>Rank</th><th>Implementation / method</th><th>${esc(f.axis)}</th><th>95% half-width</th><th>Success / attempts</th><th>Failure rate</th></tr></thead><tbody>${rows}</tbody></table></div><p class="table-caption">Source: ${f.sources.map(s=>`<a href="downloads/${s.path.split('/').pop()}" download>${esc(s.path.split('/').pop())}</a>`).join(' + ')}. ${f.table==='filter_summary'?'Up to 10 independent datasets; fast methods have 100 trials and costly methods 10.':f.table==='native_scores'?'Same saved observations; 100 repeats for most methods, 10 for Gumbel / PyDPF OT.':f.table==='learning_summary'?'10 datasets per method.':'100 repeats for fast methods; 10 for costly methods at N=128.'}</p></details></article>`;return true;}

export function paperResultLesson(){return{
id:'results',group:'TEST THE CLAIM',title:'Explore our results',subtitle:'One figure. One question. One supported finding.',goal:'Read each result like a paper figure: understand its metric, identify the best observed result, and state what the benchmark shows.',sections:[
{id:'first-principle',title:'First principle: read one question at a time',html:`<p class="lead">Start with Figure 1 and read downward. Each figure tests one property. You do not need to choose filters or decode a crowded scatterplot.</p><p><b>Read in this order:</b> question → metric meaning → plot → caption → finding. Each dot is a method’s recorded mean; whiskers show a 95% confidence interval where one is available. Teal identifies our eigen baseline. Blue marks the best observed comparator.</p><p>“Best” means the lowest or highest recorded mean <em>for the displayed task and settings</em>. It is not a claim that a method wins on every task. Close means with overlapping intervals need a planned statistical comparison before a superiority claim.</p><details class="worked-example"><summary>A small example: what is a result figure telling me?</summary><p>If the true state is 2 and an estimate is 3, its error is 1. If a second estimate is 2.5, its error is 0.5. A benchmark repeats such comparisons, summarizes them with a defined metric, and shows uncertainty in that summary. Before comparing two numbers, check that they use the same truth, data, and settings.</p></details>`},
...paperFigures.map(f=>({id:`figure-${f.id}`,title:`${f.number}. ${f.title}`,outline:`${f.number}. ${['Covariance','Mixture shape','Linear tracking','Nonlinear tracking','Likelihood gradient','Scale fitting','Gap recovery','CPU runtime'][f.number-1]}`,html:'',lab:`paper-${f.id}`})),
{id:'overall',title:'What the figures say about our claim',html:`<p><b>The moment claim is supported under its stated conditions.</b> Eigen matches covariance to numerical precision in Figure 1. <b>The full-distribution claim is not supported.</b> Its mixture shape error remains larger than the best classical comparator in Figure 2.</p><p><b>There is a useful linear-gradient result.</b> Eigen has the lowest observed score MSE in Figure 5. <b>That is not a universal filtering, learning, or speed win.</b> Figures 3–4 and 6–8 test those other questions separately.</p><p>All plots come from completed measurements, not browser simulations. Full-rank conditions and regularization limits are explained in <a href="#/eigen">lesson 6</a>; metric derivations are in <a href="#/metrics">lesson 9</a>. Download <a href="downloads/BENCHMARK-REPORT.md" download>the benchmark report</a> or <a href="downloads/NATIVE-CHECKS.md" download>native checks and failures</a> for the full scope.</p>`},
{id:'explorer',title:'Optional: explore other tasks and settings',html:`<p>After reading the figures, use the full explorer for other particle counts, dimensions, metrics, and native model results.</p><details id="advanced-explorer"><summary>Open the full interactive results explorer</summary><div data-lab="results"></div></details>`},
{id:'scope',title:'What stays outside these figure claims',html:`<p>The selected figures use N=128 to keep comparisons readable. The main run also includes N=32,512,2048 where supported. Costly-method grids are smaller. All timing results are CPU only; process memory includes imports/JIT, and the runtime plot includes integration overhead.</p><p>The main suite records 28 PFJAX Gaussian-resampler UNGM numerical failures and 33 explicit exclusions. Supplemental native FilterFlow filtering completed 29 of 30 trials. Selected upstream tests report 55 passed and 4 failed. Those native tasks and tests are a separate evidence layer; they are not silently merged into the shared-model rankings.</p><p>Static intervals repeat seeds on one fixed cloud. Filter intervals cluster by independent dataset, rather than treating all particle-filter seeds as independent datasets. A confidence interval for mean error is not a credible interval for the next hidden state. Native likelihood-gradient summaries have no interval; the figure shows that limit explicitly.</p>`}
],quiz:{prompt:'Figure 1 gives eigen almost zero covariance error, but Figure 2 gives it a larger W1 than a classical method. What does this show?',options:['Moment matching and probability-shape fidelity are different properties.','The two figures must contradict each other.','Eigen must win every full-filter test.'],answer:0,explanation:'The figures answer different questions. Mean and covariance do not uniquely determine a distribution’s probability shape.'},sources:['cuthbert','pfjax','douc','models','kalman']};}
